import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import fs from "node:fs/promises";

import { closeDb, getDb } from "@/lib/db/client";
import { ensureWorkspaceDefaults } from "@/lib/services/settings";

/**
 * Migration 019 gives an imported message an honest source value.
 *
 * A message the importer wrote was not sent by smtp, fetched by imap, seeded or generated by the
 * portal — and calling it `imap` would claim a mailbox connection that did not exist.
 */

const SQL = readFileSync("src/db/migrations/019_legacy_message_source.sql", "utf8");
const STATEMENTS = SQL.split("\n")
  .filter((line) => !line.trim().startsWith("--"))
  .join("\n")
  .split(";")
  .map((statement) => statement.trim())
  .filter(Boolean);

async function run() {
  const db = await getDb();
  for (const statement of STATEMENTS) await db.query(statement);
}

let accountId = "";

beforeAll(async () => {
  const db = await getDb();
  await ensureWorkspaceDefaults();
  const account = await db.query<{ id: string }>(
    `INSERT INTO email_accounts (id, name, provider, email_address, normalized_email, from_name, status)
     VALUES (gen_random_uuid(), 'Migration 019', 'sandbox', 'migration-019@example.test',
             'migration-019@example.test', 'Migration 019', 'connected')
     RETURNING id`,
  );
  accountId = account.rows[0].id;
});
afterAll(async () => {
  const db = await getDb();
  await db.query(`DELETE FROM messages WHERE account_id = $1`, [accountId]);
  await db.query(`DELETE FROM email_accounts WHERE id = $1`, [accountId]);
  await closeDb();
  const dir = process.env.PGLITE_DIR;
  if (dir && dir.startsWith(".data/test-vitest-")) await fs.rm(dir, { recursive: true, force: true });
});

describe("migration 019", () => {
  it("accepts an imported message, and keeps the four sources that already existed", async () => {
    await run();
    const db = await getDb();
    let uid = 900;
    for (const source of ["smtp", "imap", "seed", "system", "legacy_import"]) {
      uid += 1;
      await db.query(
        `INSERT INTO messages (id, account_id, direction, source, folder, uidvalidity, uid, message_id,
                               from_email, to_emails, subject, body_text, sent_at, is_read)
         VALUES (gen_random_uuid(), $1, 'inbound', $2, 'INBOX', 1, $3, $4, 'a@b.test', '[]'::jsonb,
                 'Subject', 'Body', now(), true)`,
        [accountId, source, uid, `<migration-019-${source}@example.test>`],
      );
    }

    const imported = await db.query<{ n: number }>(
      `SELECT count(*)::int AS n FROM messages WHERE account_id = $1 AND source = 'legacy_import'`,
      [accountId],
    );
    expect(imported.rows[0].n).toBe(1);

    // an invented value is still refused
    await expect(
      db.query(
        `INSERT INTO messages (id, account_id, direction, source, folder, uidvalidity, uid, message_id,
                               from_email, to_emails, subject, body_text, sent_at, is_read)
         VALUES (gen_random_uuid(), $1, 'inbound', 'invented', 'INBOX', 1, 999, '<x@example.test>',
                 'a@b.test', '[]'::jsonb, 'Subject', 'Body', now(), true)`,
        [accountId],
      ),
    ).rejects.toThrow();
  });

  it("is safe to run again, twice over", async () => {
    await run();
    await run();
    const db = await getDb();
    const constraint = await db.query<{ definition: string }>(
      `SELECT pg_get_constraintdef(oid) AS definition FROM pg_constraint
        WHERE conname = 'messages_source_check'`,
    );
    expect(constraint.rows[0].definition).toContain("legacy_import");
    expect(constraint.rows[0].definition).toContain("smtp");
    expect(constraint.rows[0].definition).toContain("seed");
    expect(constraint.rows[0].definition).toContain("system");
  });
});